import { and, desc, eq, isNull, or } from \"drizzle-orm\";
import { OwnershipHandoverError } from \"@/lib/errors\";
import { newId } from \"@/lib/id\";
import { PermissionDeniedError } from \"@/lib/permissions\";
import { getDb, members, organizations, ownershipHandovers } from \"@/server/db\";
import { toIsoTimestamp } from \"@/types/common\";
import type { OrgId, UserId } from \"@/types/common\";
import type { Actor } from \"@/types/member\";
import type { OwnershipHandover, OwnershipHandoverStatus } from \"@/types/organization\";
import { NotFoundError, requireFound } from \"@/server/services/_support\";
import { toMember, toOrganization } from \"./_mappers\";

type Row = typeof ownershipHandovers."'$inferSelect;
function map(row: Row): OwnershipHandover {
  return { ...row, orgId: row.orgId as OrgId, fromUserId: row.fromUserId as UserId,
    toUserId: row.toUserId as UserId, createdAt: toIsoTimestamp(row.createdAt),
    expiresAt: toIsoTimestamp(row.expiresAt), resolvedAt: row.resolvedAt === null ? null : toIsoTimestamp(row.resolvedAt) };
}

export function assertRecordedOwner(actor: Actor, orgId: OrgId): void {
  const org = requireFound(getDb().select().from(organizations).where(eq(organizations.id, orgId)).get(), "Organization", orgId);
  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:manage_billing", {
      action: "org:manage_billing", resourceKind: "organization", allowed: false, reason: "denied_by_role",
    });
  }
}

function latestPending(orgId: OrgId): Row | undefined {
  return getDb().select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).orderBy(desc(ownershipHandovers.createdAt)).get();
}

export function pending(orgId: OrgId): OwnershipHandover | null {
  const row = latestPending(orgId);
  return row && Date.now() < Date.parse(row.expiresAt) ? map(row) : null;
}

export function initiate(actor: Actor, orgId: OrgId, toUserId: UserId): OwnershipHandover {
  return getDb().transaction((tx) => {
    assertRecordedOwner(actor, orgId);
    if (actor.userId === toUserId) throw new OwnershipHandoverError("self");
    const target = tx.select().from(members).where(and(eq(members.orgId, orgId), eq(members.userId, toUserId), isNull(members.archivedAt), eq(members.status, "active"))).get();
    if (!target) throw new NotFoundError("Member", toUserId);
    const now = new Date();
    const previous = latestPending(orgId);
    if (previous) {
      if (now.getTime() < Date.parse(previous.expiresAt)) throw new OwnershipHandoverError("pending_exists");
      tx.update(ownershipHandovers).set({ status: "expired", resolvedAt: previous.expiresAt }).where(eq(ownershipHandovers.id, previous.id)).run();
    }
