  });
}

export function resolve(actor: Actor, orgId: OrgId, status: "accepted" | "declined" | "canceled") {
  return getDb().transaction((tx) => {
    if (status === "canceled") assertRecordedOwner(actor, orgId);
    const offer = latestPending(orgId);
    if (!offer || (status === "canceled" ? offer.fromUserId : offer.toUserId) !== actor.userId) throw new OwnershipHandoverError("nothing_pending");
    if (Date.now() >= Date.parse(offer.expiresAt)) throw new OwnershipHandoverError(status === "canceled" ? "nothing_pending" : "expired");
