      for (const [member, role] of [[to, "owner"], [from, "admin"]] as const) {
        if (member === from && member.role !== "owner") continue;
        if (member.role === role) continue;
        tx.update(members).set({ role, updatedAt: stamp }).where(eq(members.id, member.id)).run();
